# Edge cases: list too short (no pair), duplicates needed (e.g. t=6 with [3,3]).
# Main: hash-map complement lookup.
def two_sum(nums, t):
    seen = {}
    for i, x in enumerate(nums):
        if t - x in seen:
            return [seen[t-x], i]
        seen[x] = i
    return []
```

