# Edge cases: empty string (valid), unmatched close at start, unmatched opens at end.
# Main: stack of openers; pop on matching close.
def is_valid_parens(s):
    pairs = {')':'(',']':'[','}':'{'}
    stack = []
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()
    return not stack
```

