# Edge cases: empty list, no sublists, mixed sublists and items, deeply nested (only flatten one level).
# Main: extend or append per item.
def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(item)
        else:
            result.append(item)
    return result
```

