# Edge cases: lst longer than length (truncate), lst empty (all fill), length<=0 (empty).
# Main: slice or pad.
def pad_list(lst, length, fill=0):
    if length <= 0:
        return []
    if len(lst) >= length:
        return lst[:length]
    return lst + [fill] * (length - len(lst))
```

