# Edge cases: empty list (return ''), one string (return it), no common prefix (return '').
# Main: shrink prefix while any string doesn't start with it.
def longest_common_prefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix
```

