# Edge cases: empty list (return []), no overlaps, all overlap, touching intervals (depends on inclusive/exclusive).
# Main: sort by start, sweep extending or starting new.
def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [list(intervals[0])]
    for s, e in intervals[1:]:
        if s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return merged
